"""Generate INTERVENTION_RESULTS.md tables directly from the protocol JSON logs (no hand-copied numbers)."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
L = ["# Intervention results (generated by scripts/make_tables.py from logs/protocol_*.json)\n",
     "One row per model and site. Rates are model-relative and computed on matched pairs on which the model's own decisions differ. The column `nec` is the fraction of pairs whose decisions still differ after pair-mean ablation of S_rel, so lower is stronger necessity. The column `suff` is sufficiency: the fraction of pairs keeping their decision after complement interchange. `addR2` is the additive R² of the S_rel coordinates. Surrogate columns give (accuracy, pair_flip) after replacing the S_rel coordinates; `exact` is the reference. `path` reports MLP-path versus direct-path IIA. `manifold` is the patched-state nearest-neighbour distance divided by the natural nearest-neighbour distance.\n"]
for tag, title in (("E1", "E1: historical seeds 2-4 (never used for mediator analysis)"), ("E2", "E2: NEW seeds 7-9"),
                   ("E3", "E3: NEW aggregate-only nonlinear control AGG-NL, seeds 0-4"),
                   ("E4a", "E4a: gauss evaluation inputs + new pair seed, seeds 2-4"), ("E4b", "E4b: gauss evaluation inputs + new pair seed, seeds 7-9")):
    d = json.load(open(ROOT / "logs" / f"protocol_{tag}.json"))
    L.append(f"\n## {title}\n")
    L.append("| model | site | verdict | k | cut | S_rel | S_das | S_grad | S_pca | S_alt | S_rand mean / max | nec | suff | addR2 | surrogates: exact / additive / linear / aggregate | path (mlp / direct) | manifold |")
    L.append("|" + "---|" * 17)
    for key, sites in d.items():
        for site, r in sites.items():
            if "verdict" not in r:
                L.append(f"| {key} | {site} | no relation-sensitive behaviour: model decisions differ on {r['n_pairs_model_differs']} of 500 matched pairs; contrast energy {r['contrast_energy_ratio']:.3f}; acc {r['acc_ev']:.3f} |" + " |" * 14)
                continue
            f = lambda x: "-" if x is None else f"{x:.3f}"
            I = r["iia"]; S = r["surrogates"]
            surr = " / ".join(f"({v['acc']:.3f}, {v['pair_flip']:.3f})" for v in S.values())
            ps = r.get("path_split"); ps = f"{ps['mlp_path_only']:.2f} / {ps['direct_path_only']:.2f}" if ps else "-"
            L.append(f"| {key} | {site} | {r['verdict']} | {r['k']} | {f(r['iia_full_site'])} | {f(I['S_rel'])} | {f(I['S_das'])} | {f(I['S_grad'])} | {f(I['S_pca'])} | {f(I['S_alt'])} | {f(I['S_rand_mean'])} / {f(I['S_rand_max'])} | {f(r['necessity']['flip_after'])} | {f(r['sufficiency'])} | {f(r['additive_R2'])} | {surr} | {ps} | {r['manifold']['ratio']:.1f} |")
(ROOT / "INTERVENTION_RESULTS.md").write_text("\n".join(L) + "\n")
print("ok", len(L))
